-- Source: CourtListener ? Judge & Financial Disclosure Database (16191 rows)
-- Generated by scripts/gen_mart_models.py
-- Fixed 2026-09-20: DATE_CREATED/DATE_MODIFIED/DATE_COMPLETED/DATE_DOB/DATE_DOD
-- were bare try_to_date() casts -- live-checked today: all 5 columns are
-- 100% clean (0 pure-digit values across 16,191 rows), so no active
-- epoch-1970 misread right now, but the same shape that hit BIRTH_DATE in
-- justice__intl_opensanctions (~6.8k rows collapsed onto 1970-01-01) is one
-- bad load away here too. Replaced in place with the guarded stg_date macro
-- (macros/staging_casts.sql). FTM_TOTAL_RECEIVED was already on the guarded
-- ripple_num macro, untouched. Kept on source() (not ref()) -- a matching
-- staging model exists (stg_fed_courtlistener_judges__records) but it types
-- date_created/date_modified/date_completed as TIMESTAMP (stg_ts) where this
-- mart keeps DATE -- swapping would silently change those 3 column types.

with source as (
    select * from {{ source('ripple_raw', 'FED_COURTLISTENER_JUDGES') }}
)

select
    ID as id,
    {{ stg_date('DATE_CREATED') }} as date_created,
    {{ stg_date('DATE_MODIFIED') }} as date_modified,
    {{ stg_date('DATE_COMPLETED') }} as date_completed,
    FJC_ID as fjc_id,
    SLUG as slug,
    NAME_FIRST as name_first,
    NAME_MIDDLE as name_middle,
    NAME_LAST as name_last,
    NAME_SUFFIX as name_suffix,
    {{ stg_date('DATE_DOB') }} as date_dob,
    nullif(trim(DATE_GRANULARITY_DOB), '') as date_granularity_dob,
    {{ stg_date('DATE_DOD') }} as date_dod,
    nullif(trim(DATE_GRANULARITY_DOD), '') as date_granularity_dod,
    DOB_CITY as dob_city,
    DOB_STATE as dob_state,
    DOB_COUNTRY as dob_country,
    DOD_CITY as dod_city,
    DOD_STATE as dod_state,
    DOD_COUNTRY as dod_country,
    GENDER as gender,
    RELIGION as religion,
    {{ ripple_num('FTM_TOTAL_RECEIVED') }} as ftm_total_received,
    FTM_EID as ftm_eid,
    HAS_PHOTO as has_photo,
    IS_ALIAS_OF_ID as is_alias_of_id
from source
